package com.sdprep.chat;

/**
 * A stored chat message.
 *
 * @param sequence        assigned by the server, increasing within one conversation; defines the order everyone sees
 * @param clientMessageId generated by the sender's device; lets the server ignore a resend of the same message
 */
public record Message(String conversationId, long sequence, String clientMessageId,
                      String senderId, String text, long sentAtMillis) {
}
